import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on mean difference and t-statistic
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':
            mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            t_stat = abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic)
            if abs(mean_diff) > 0.15 or t_stat > 2.0:
                strong_candidates.append((fid, mean_diff, t_stat))

    # Sort by t-statistic descending
    strong_candidates.sort(key=lambda x: x[2], reverse=True)

    # Remove near-duplicates (correlated features)
    filtered_candidates = []
    excluded = set()
    for fid, _, _ in strong_candidates:
        if fid in excluded:
            continue
        filtered_candidates.append(fid)
        # Find correlated features to exclude
        for other_fid in feats.ids:
            if other_fid == fid or other_fid in excluded:
                continue
            col_a = feats.column(fid)
            col_b = feats.column(other_fid)
            if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0,1]) >= 0.6:
                excluded.add(other_fid)

    # If no strong candidates, return empty design
    if len(filtered_candidates) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Try to identify a single driver from top candidates
    drivers = ()
    for fid in filtered_candidates[:3]:
        # Check if this feature shows significant association with outcome
        col = feats.column(fid)
        t_stat = abs(stats.ttest_ind(feats.x[feats.y==1, col], feats.x[feats.y==0, col]).statistic)
        if t_stat > 2.0:
            drivers = (fid,)
            break

    # Build regression variables
    columns = tuple(filtered_candidates[:10])  # Top 10 features
    products = ()
    loadings = {}

    # Add interaction terms for top correlated pairs
    corr_pairs = [
        ('JMEM13', 'HNR10'), ('ARK19', 'EEP13'), ('HMD6L', 'HFZZ16A'),
        ('UITZ7', 'EEP13'), ('XVFL18A', 'EEP13'), ('JMEM13', 'ARK19'),
        ('UITZ7', 'ARK19'), ('QFDL16', 'EEP13'), ('XVFL18A', 'ARK19')
    ]

    # Only add products involving our selected driver if we have one
    if drivers:
        for a, b in corr_pairs:
            if a in columns and b in columns and a != b:
                products += ((a, b),)
                break

    # Simple weighted score using top features
    for i, fid in enumerate(columns):
        col = feats.column(fid)
        # Weight by t-statistic
        t_stat = abs(stats.ttest_ind(feats.x[feats.y==1, col], feats.x[feats.y==0, col]).statistic)
        loadings[fid] = t_stat

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

